const W=id=>document.getElementById('w-'+id),english=document.documentElement.lang==='en',L=(vi,en)=>english?en:vi,F=(v,n=2)=>Number(v).toLocaleString(english?'en-US':'vi-VN',v>0&&v<10**(-n)?{maximumSignificantDigits:3}:{maximumFractionDigits:n});let waterMode='auto',waterRows=[],waterChosen=null,waterSort='diameter',waterDirection=1,waterUnit=3600;
const pipeDiameters=[15,20,25,32,40,50,65,80,100,125,150,200,250,300,350,400,450,500,600,700,800,900,1000];
function waterInput(){return{q:+W('flow').value/+W('unit').value,t:+W('temp').value,e:+W('rough').value,l:+W('length').value,v:+W('vmax').value,r:+W('rmax').value,d:+W('diameter').value,s:+W('slope').value/100,fill:+W('fill').value/100,n:+W('n').value,min:+W('vmin').value,max:+W('gvmax').value,gravity:W('system').value==='drain'};}
function waterUpdate(){const x=waterInput(),valid=Object.values(x).filter(v=>typeof v==='number').every(Number.isFinite)&&x.q>0&&(waterMode!=='check'||x.d>=5&&x.d<=3000)&&(x.gravity?x.s>0&&x.s<=1&&x.fill>=.1&&x.fill<=.8&&x.n>=.005&&x.n<=.1&&x.min>=0&&x.max>0&&x.max>=x.min:x.t>=1&&x.t<=80&&x.e>=0&&x.l>=0&&x.v>0&&x.r>0);W('error').hidden=valid;waterRows=[];if(valid){for(const d of waterMode==='check'?[x.d]:pipeDiameters){const r=x.gravity?gravityPipe(x.q,d,x.s,x.n,x.fill):pressurePipe(x.q,d,x.t,x.e,x.l);const qualifies=x.gravity?!r.overCapacity&&r.V>=x.min&&r.V<=x.max:r.V<=x.v&&r.R<=x.r;if(waterMode==='check'||qualifies)waterRows.push(r);}if(waterRows.length){waterRows.sort((a,b)=>x.gravity?a.diameter-b.diameter:b.R-a.R);waterRows=waterRows.slice(0,30);waterChosen=waterRows[0];waterChosen.recommended=waterMode==='auto';waterRender();waterTable();return;}}W('error').hidden=false;W('error').textContent=valid?L('Không có đường kính phù hợp. Kiểm tra lưu lượng, giới hạn hoặc dùng chế độ kiểm tra đường kính riêng.','No qualifying diameters. Check flow and limits, or check a custom internal diameter.'):L('Thông số không hợp lệ. Kiểm tra các giới hạn nhập liệu; độ đầy 10–80%, nhiệt độ nước 1–80 °C.','Invalid inputs. Check input limits; maximum depth 10–80%, water temperature 1–80 °C.');['size','area','detail','extra','velocity','friction','loss'].forEach(id=>W(id).textContent='—');W('status').textContent=L('Chưa có kết quả','No results');W('status').className='status warning';W('count').textContent='0';W('rows').innerHTML='';W('sub').textContent='';}
function waterRender(){const r=waterChosen,x=waterInput(),g=x.gravity;W('caption').textContent=waterMode==='check'?L('ĐƯỜNG KÍNH KIỂM TRA','DIAMETER TO CHECK'):r.recommended?L('ĐƯỜNG KÍNH ĐỀ XUẤT','RECOMMENDED DIAMETER'):L('ĐƯỜNG KÍNH ĐANG CHỌN','SELECTED DIAMETER');W('size').innerHTML='Ø '+F(r.diameter,1)+' <small>mm</small>';W('sub').textContent=L('Đường kính trong · ','Internal diameter · ')+W('system').selectedOptions[0].textContent;const warning=g?r.overCapacity||r.V<x.min||r.V>x.max:r.V>x.v||r.R>x.r||r.Re>=2300&&r.Re<4000;W('status').className='status'+(warning?' warning':'');W('status').textContent=g&&r.overCapacity?L('Không đủ năng lực thoát','Insufficient capacity'):!g&&r.Re>=2300&&r.Re<4000?L('Dòng chuyển tiếp','Transitional flow'):warning?L('Vượt giới hạn','Outside limits'):L('Đạt tiêu chí','Within limits');W('area').textContent=F(Math.PI*(r.diameter/1000)**2/4,5)+' m²';W('detail-label').firstChild.textContent=g?L('Độ đầy y/D','Flow depth y/D'):'Reynolds';W('detail').textContent=g?r.overCapacity?'—':F(r.fill*100,1)+'%':F(r.Re,0);W('extra-label').firstChild.textContent=g?L('Khả năng thoát tại độ đầy tối đa','Capacity at maximum depth'):L('Hệ số ma sát Darcy','Darcy friction factor');W('extra').textContent=g?F(r.capacity*3600)+' m³/h':F(r.f,4);W('velocity').textContent=r.overCapacity?'—':F(r.V);W('vnote').textContent=g?F(x.min)+' – '+F(x.max)+' m/s':L('Tối đa: ','Maximum: ')+F(x.v)+' m/s';W('metric-label').textContent=g?L('Độ đầy dòng thực','Actual depth ratio y/D'):L('Suất tổn thất ma sát','Friction loss rate');W('friction-unit').textContent=g?'%':'Pa/m';W('friction').textContent=g?r.overCapacity?'—':F(r.fill*100,1):F(r.R);W('pnote').textContent=L('Tối đa: ','Maximum: ')+F(g?x.fill*100:x.r)+(g?'%':' Pa/m');W('loss-label').textContent=g?L('Năng lực thoát','Drainage capacity'):L('Tổn thất đoạn ống','Section pressure loss');W('loss-unit').textContent=g?'m³/h':'kPa';W('loss').textContent=F(g?r.capacity*3600:r.loss/1000);W('lnote').textContent=g?L('Tại độ đầy tối đa đã nhập','At the maximum depth entered'):L('Cột áp ma sát: ','Friction head: ')+F(r.head)+' mH₂O';W('explanation').textContent=g?L('Manning tính dòng đều theo độ dốc và tiết diện ướt. Độ đầy hiển thị là độ sâu tính từ lưu lượng thực; năng lực thoát tính tại độ đầy tối đa. Không dùng chế độ này cho ống có áp.','Manning models uniform flow using slope and wetted area. Actual depth is solved from the flow rate; capacity is evaluated at the maximum depth. This mode is for gravity drainage, not pressurized pipes.'):L('Darcy–Weisbach tính ma sát theo đường kính trong, nhiệt độ và độ nhám. Tổn thất chỉ bao gồm ống thẳng; cần cộng phụ kiện và thiết bị khi chọn bơm.','Darcy–Weisbach calculates friction from internal diameter, temperature and roughness. Straight pipe losses only; add fittings and equipment when selecting pumps.');W('th-R').textContent=g?L('Độ đầy (%)','Depth ratio y/D (%)'):L('Suất tổn thất (Pa/m)','Friction loss rate (Pa/m)');W('th-loss').textContent=g?L('Năng lực (m³/h)','Capacity (m³/h)'):L('Tổn thất (kPa)','Loss (kPa)');W('table-note').textContent=g?L('Đủ năng lực thoát và đạt giới hạn vận tốc. Đề xuất đường kính nhỏ nhất.','Sufficient capacity and velocities within limits. The smallest qualifying diameter is recommended.'):L('Tối đa 30 đường kính có ma sát gần giới hạn nhất, không vượt giới hạn vận tốc.','Up to 30 internal diameters closest to the friction limit and within the velocity limit.');}
function waterTable(){const g=waterInput().gravity,key=waterSort==='R'&&g?'fill':waterSort==='loss'&&g?'capacity':waterSort;waterRows.sort((a,b)=>waterDirection*((a[key]??Infinity)-(b[key]??Infinity))||a.diameter-b.diameter);W('count').textContent=waterRows.length+' '+L('phương án','options');W('rows').innerHTML=waterRows.map((r,i)=>`<tr class="candidate ${r===waterChosen?'chosen':''}"><td><button class="row-button" aria-pressed="${r===waterChosen}" data-water-row="${i}">Ø ${F(r.diameter,1)}${r.recommended?' <span class="badge">'+L('Đề xuất','Recommended')+'</span>':''}</button></td><td>${r.overCapacity?'—':F(r.V)}</td><td>${g?r.overCapacity?'—':F(r.fill*100,1):F(r.R)}</td><td>${F(g?r.capacity*3600:r.loss/1000)}</td></tr>`).join('');document.querySelectorAll('#w-rows tr').forEach((tr,i)=>tr.onclick=()=>{waterChosen=waterRows[i];waterRender();waterTable();});document.querySelectorAll('[data-w-sort]').forEach(b=>{b.closest('th').setAttribute('aria-sort',b.dataset.wSort===waterSort?(waterDirection===1?'ascending':'descending'):'none');b.querySelector('.sort-icon').textContent=b.dataset.wSort===waterSort?(waterDirection===1?'↑':'↓'):'↕';});}
function waterSystem(){const g=W('system').value==='drain';W('gravity').hidden=!g;W('pressure').hidden=g;if(!g){W('vmax').value=W('system').value==='chiller'?2:1.5;W('rmax').value=W('system').value==='chiller'?300:200;W('temp').value=W('system').value==='chiller'?7:20;}waterSort=g?'diameter':'R';waterDirection=g?1:-1;waterUpdate();}
W('system').onchange=waterSystem;W('material').onchange=()=>{const values={steel:[.045,.013],plastic:[.0015,.011],copper:[.0015,.011]};const v=values[W('material').value];if(v){W('rough').value=v[0];W('n').value=v[1];}waterUpdate();};['rough','n'].forEach(id=>W(id).addEventListener('input',()=>W('material').value='custom'));
document.querySelectorAll('.inputs input').forEach(el=>el.addEventListener('input',waterUpdate));W('unit').onchange=()=>{W('flow').value=+(+W('flow').value/waterUnit*+W('unit').value).toFixed(6);waterUnit=+W('unit').value;waterUpdate();};document.querySelectorAll('#w-modes button').forEach(b=>b.onclick=()=>{waterMode=b.dataset.mode;W('check').hidden=waterMode!=='check';document.querySelectorAll('#w-modes button').forEach(v=>v.classList.toggle('selected',v===b));waterUpdate();});document.querySelectorAll('[data-w-sort]').forEach(b=>b.onclick=()=>{waterDirection=waterSort===b.dataset.wSort?-waterDirection:1;waterSort=b.dataset.wSort;waterTable();});W('reset').onclick=()=>{Object.entries({flow:10,unit:3600,diameter:100,system:'chiller',material:'steel',rough:.045,length:10,slope:1,fill:70,n:.013,vmin:.6,gvmax:3}).forEach(([id,v])=>W(id).value=v);waterUnit=3600;waterMode='auto';W('check').hidden=true;document.querySelectorAll('#w-modes button').forEach(b=>b.classList.toggle('selected',b.dataset.mode==='auto'));waterSystem();};waterSystem();
